UIScoreExplosionEmitter=function(game){Phaser.Particles.Arcade.Emitter.call(this,game,0,0,60);this.particleClass=UIScoreExplosionParticle;this.makeParticles('playerpanel',['smoke0','smoke1','smoke2']);this.minParticleSpeed.setTo(UIConstants.SCORE_EXPLOSION_MIN_X_SPEED,UIConstants.SCORE_EXPLOSION_MIN_Y_SPEED);this.maxParticleSpeed.setTo(UIConstants.SCORE_EXPLOSION_MAX_X_SPEED,UIConstants.SCORE_EXPLOSION_MAX_Y_SPEED);this.particleDrag.setTo(UIConstants.SCORE_EXPLOSION_DRAG,UIConstants.SCORE_EXPLOSION_DRAG);this.setAlpha(0.8,1.0);this.setRotation(-100,100);this.minParticleScale=0.7;this.maxParticleScale=1.0;this.gravity=0;this.kill();this.visible=false;};UIScoreExplosionEmitter.prototype=Object.create(Phaser.Particles.Arcade.Emitter.prototype);UIScoreExplosionEmitter.prototype.constructor=UIScoreExplosionEmitter;UIScoreExplosionEmitter.prototype.update=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.update.call(this);if(this.countLiving()==0){this.kill();this.visible=false;}};UIScoreExplosionEmitter.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.postUpdate.call(this);};UIScoreExplosionEmitter.prototype.spawn=function(x,y,width){this.revive();this.visible=true;this.x=x;this.y=y;this.width=width;this.explode(2500,60);};UIScoreExplosionEmitter.prototype.retire=function(){this.kill();this.visible=false;this.callAll('retire');};